}
.store-hero .hero-links {
  margin-top: 16px;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: var(--fs-caption);
}

/* --- Product Icon Bar --- */
.icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  padding: 20px 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar a {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-primary);
