/* ============================================================
   ORCHARD — Premium Tech E-Commerce Store
   Design System & Styles
   ============================================================ */

/* --- Design Tokens --- */
:root {
  --color-primary: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #004499;
  --color-bg: #fff;
  --color-bg-alt: #f5f5f7;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --color-white: #fff;
  --color-ribbon: #1d1d1f;

  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;

  --fs-display: clamp(2.5rem, 5vw, 3.5rem);
  --fs-h1: clamp(2rem, 4vw, 3rem);
  --fs-h2: clamp(1.75rem, 3.5vw, 2.5rem);
  --fs-h3: clamp(1.25rem, 2vw, 1.75rem);
  --fs-h4: 1.3125rem;
  --fs-body-lg: 1.3125rem;
  --fs-body: 1.0625rem;
  --fs-caption: 0.875rem;
  --fs-small: 0.75rem;

  --nav-height: 48px;
  --ribbon-height: 44px;
  --section-padding: 80px;
  --card-radius: 20px;
  --btn-radius: 22px;
  --max-width: 1200px;
  --carousel-gap: 16px;
}

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-stack);
  font-size: var(--fs-body);
  line-height: 1.47;
  color: var(--color-primary);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img { max-width: 100%; display: block; }
a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Ribbon Banner --- */
.ribbon {
  background: var(--color-ribbon);
  color: var(--color-white);
  text-align: center;
  padding: 12px 20px;
  font-size: var(--fs-caption);
  line-height: 1.43;
}
.ribbon a { color: var(--color-accent); }
.ribbon a:hover { text-decoration: underline; }

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  height: var(--nav-height);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}
.nav-logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
  text-decoration: none;
  letter-spacing: -0.02em;
}
.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}
.nav-links a {
  font-size: var(--fs-caption);
  color: var(--color-primary);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity 0.2s;
}
.nav-links a:hover { opacity: 1; text-decoration: none; }
.nav-links a.active { opacity: 1; font-weight: 600; }
.nav-icons {
  display: flex;
  gap: 16px;
  align-items: center;
}
.nav-icons svg { width: 18px; height: 18px; fill: var(--color-primary); opacity: 0.8; }

/* --- Section Containers --- */
.section {
  padding: var(--section-padding) 0;
}
.section--alt {
  background: var(--color-bg-alt);
}
.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section-header {
  margin-bottom: 32px;
}
.section-header h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.section-header p {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 6px;
}

/* --- Hero (Store page) --- */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
}
.store-hero h1 {
  font-size: var(--fs-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}
.store-hero .subtitle {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 8px;
}
.store-hero .hero-links {
  margin-top: 16px;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: var(--fs-caption);
}

/* --- Product Icon Bar --- */
.icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  padding: 20px 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar a {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-primary);
  font-size: var(--fs-small);
  white-space: nowrap;
  min-width: 70px;
  transition: transform 0.2s;
}
.icon-bar a:hover { transform: translateY(-2px); text-decoration: none; }
.icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: background 0.2s;
}
.icon-bar a:hover .icon-circle { background: #e8e8ed; }

/* --- Carousel --- */
.carousel {
  position: relative;
  padding-bottom: 12px;
}
.carousel-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}
.carousel-top h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.carousel-top p {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 4px;
}
.carousel-arrows {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}
.carousel-arrow {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
  transition: background 0.2s, opacity 0.2s;
  border: 1px solid var(--color-border);
}
.carousel-arrow:hover { background: #e8e8ed; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }
.carousel-arrow svg { width: 16px; height: 16px; }

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px;
  padding-bottom: 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

/* --- Product Card (carousel) --- */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.product-card-image {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  position: relative;
  overflow: hidden;
}
.product-card-body {
  padding: 20px;
}
.product-card .badge {
  display: inline-block;
  font-size: var(--fs-small);
  font-weight: 600;
  color: #bf4800;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.product-card h3 {
  font-size: var(--fs-h4);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}
.product-card .tagline {
  color: var(--color-secondary);
  font-size: var(--fs-caption);
  margin-bottom: 12px;
  line-height: 1.4;
}
.product-card .price {
  font-size: var(--fs-body);
  font-weight: 600;
}
.product-card .monthly {
  font-size: var(--fs-caption);
  color: var(--color-secondary);
  margin-top: 2px;
}
.product-card .note {
  font-size: var(--fs-small);
  color: var(--color-accent);
  margin-top: 6px;
}

/* Card image color variants */
.card-bg-blue { background: linear-gradient(135deg, #d4e4f7 0%, #b8cfe8 100%); }
.card-bg-purple { background: linear-gradient(135deg, #e8daf5 0%, #d4c4eb 100%); }
.card-bg-peach { background: linear-gradient(135deg, #fde8d8 0%, #f5d4bc 100%); }
.card-bg-midnight { background: linear-gradient(135deg, #2d2d3a 0%, #1a1a2e 100%); color: #fff; }
.card-bg-teal { background: linear-gradient(135deg, #d0f0e8 0%, #b0e0d4 100%); }
.card-bg-rose { background: linear-gradient(135deg, #f5e0e8 0%, #ecc8d5 100%); }
.card-bg-silver { background: linear-gradient(135deg, #eaeaef 0%, #dddde3 100%); }
.card-bg-green { background: linear-gradient(135deg, #d4edda 0%, #b8dcc4 100%); }
.card-bg-warm { background: linear-gradient(135deg, #f5eadc 0%, #ede0d0 100%); }
.card-bg-orange { background: linear-gradient(135deg, #fde5c3 0%, #f5d4a8 100%); }
.card-bg-guava { background: linear-gradient(135deg, #f8c4c4 0%, #f0aaaa 100%); }
.card-icon {
  font-size: 3.5rem;
  opacity: 0.7;
}

/* --- Homepage Hero Product Grid --- */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.product-tile {
  border-radius: var(--card-radius);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  text-align: center;
  padding: 48px 32px 0;
  min-height: 500px;
  transition: transform 0.3s;
}
.product-tile:hover { transform: scale(1.005); }
.product-tile.full-width { grid-column: 1 / -1; min-height: 560px; }

.product-tile h2 {
  font-size: var(--fs-h1);
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 8px;
}
.product-tile .tile-tagline {
  font-size: var(--fs-body-lg);
  margin-bottom: 20px;
  max-width: 400px;
}
.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
}
.product-tile .tile-ctas a {
  font-size: var(--fs-body);
  font-weight: 400;
  padding: 8px 20px;
  border-radius: var(--btn-radius);
}
.btn-primary {
  background: var(--color-accent);
  color: var(--color-white) !important;
  transition: background 0.2s;
}
.btn-primary:hover { background: var(--color-accent-hover); text-decoration: none; }
.btn-secondary {
  background: transparent;
  border: 1px solid var(--color-accent);
  color: var(--color-accent) !important;
  transition: background 0.2s;
}
.btn-secondary:hover { background: rgba(0,102,204,0.06); text-decoration: none; }
.btn-secondary-light {
  border-color: rgba(255,255,255,0.6);
  color: var(--color-white) !important;
}
.btn-secondary-light:hover { background: rgba(255,255,255,0.12); }
.btn-primary-light {
  background: var(--color-white);
  color: var(--color-primary) !important;
}
.btn-primary-light:hover { background: rgba(255,255,255,0.85); }

.tile-dark { color: var(--color-white); }
.tile-dark .tile-tagline { color: rgba(255,255,255,0.8); }

.tile-image-area {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  opacity: 0.5;
  margin-top: 24px;
  width: 100%;
}

/* Tile background colors */
.tile-phone { background: linear-gradient(180deg, #1b1b3a 0%, #0f3460 100%); }
.tile-laptop-neo { background: linear-gradient(180deg, #faf8f5 0%, #f0ebe3 100%); }
.tile-tablet-pro { background: linear-gradient(180deg, #1a1a2e 0%, #2d1b4e 100%); }
.tile-laptop-pro { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.tile-earbuds { background: linear-gradient(180deg, #fef6ee 0%, #fde5c3 100%); }
.tile-tradein { background: linear-gradient(180deg, #004d40 0%, #00695c 100%); }

/* --- Entertainment Tabs --- */
.entertainment {
  padding: var(--section-padding) 0;
  background: var(--color-primary);
  color: var(--color-white);
}
.entertainment .section-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.entertainment h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}
.ent-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.ent-tab {
  padding: 10px 24px;
  border-radius: var(--btn-radius);
  font-size: var(--fs-caption);
  font-weight: 500;
  color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  transition: all 0.25s;
}
.ent-tab:hover { background: rgba(255,255,255,0.15); color: #fff; }
.ent-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  border-color: var(--color-white);
}
.ent-panel { display: none; }
.ent-panel.active { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.ent-card {
  border-radius: 16px;
  overflow: hidden;
  transition: transform 0.3s;
}
.ent-card:hover { transform: translateY(-4px); }
.ent-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.ent-card-body {
  padding: 16px;
  background: rgba(255,255,255,0.06);
}
.ent-card-body h3 {
  font-size: var(--fs-body);
  font-weight: 600;
  margin-bottom: 8px;
}
.ent-card-body a {
  font-size: var(--fs-caption);
  color: var(--color-accent);
}
.ent-bg-1 { background: linear-gradient(135deg, #2d1b4e 0%, #4a1a6b 100%); }
.ent-bg-2 { background: linear-gradient(135deg, #1a3a5c 0%, #0f5c4a 100%); }
.ent-bg-3 { background: linear-gradient(135deg, #4a1a1a 0%, #6b3a1a 100%); }
.ent-bg-4 { background: linear-gradient(135deg, #1a2e4a 0%, #2d4a6b 100%); }

/* --- Help / Support Cards --- */
.help-card, .diff-card, .guide-card, .save-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  padding: 28px 24px;
  transition: transform 0.3s, box-shadow 0.3s;
}
.help-card:hover, .diff-card:hover, .guide-card:hover, .save-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.help-card .card-emoji, .diff-card .card-emoji, .guide-card .card-emoji, .save-card .card-emoji {
  font-size: 2rem;
  margin-bottom: 16px;
  display: block;
}
.help-card h3, .diff-card h3, .guide-card h3, .save-card h3 {
  font-size: var(--fs-h4);
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p, .diff-card p, .guide-card p, .save-card p {
  color: var(--color-secondary);
  font-size: var(--fs-caption);
  line-height: 1.5;
}

/* --- Brand Collab --- */
.brand-collab {
  border-radius: var(--card-radius);
  overflow: hidden;
  background: linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%);
  color: var(--color-white);
  padding: 60px 48px;
  display: flex;
  align-items: center;
  gap: 48px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.brand-collab-text { flex: 1; }
.brand-collab h2 { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -0.02em; margin-bottom: 8px; }
.brand-collab p { color: rgba(255,255,255,0.75); font-size: var(--fs-body-lg); margin-bottom: 20px; }
.brand-collab-visual {
  flex: 0 0 300px;
  height: 200px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  opacity: 0.5;
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  padding: 40px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.quick-link {
  padding: 10px 24px;
  border-radius: var(--btn-radius);
  border: 1px solid var(--color-border);
  font-size: var(--fs-caption);
  color: var(--color-primary);
  background: var(--color-white);
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s;
}
.quick-link:hover { background: var(--color-bg-alt); border-color: #bbb; text-decoration: none; }

/* --- Sticky Section Navigation (Category Pages) --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 90;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section-nav a {
  padding: 14px 20px;
  font-size: var(--fs-caption);
  color: var(--color-secondary);
  white-space: nowrap;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.section-nav a:hover { color: var(--color-primary); text-decoration: none; }
.section-nav a.active {
  color: var(--color-primary);
  font-weight: 600;
  border-bottom-color: var(--color-primary);
}

/* --- Category Hero --- */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-alt);
}
.category-hero h1 {
  font-size: var(--fs-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}
.category-hero .subtitle {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 8px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Promo Banner (within sections) --- */
.promo-text {
  font-size: var(--fs-caption);
  color: var(--color-accent);
  margin-top: -16px;
  margin-bottom: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

/* --- Footer --- */
.footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: 40px 0 24px;
  font-size: var(--fs-small);
  color: var(--color-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: var(--fs-caption);
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 12px;
  cursor: default;
}
.footer-col ul { display: flex; flex-direction: column; gap: 8px; }
.footer-col a {
  color: var(--color-secondary);
  font-size: var(--fs-small);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--color-primary); }
.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 16px;
  font-size: var(--fs-small);
  line-height: 1.6;
  color: #86868b;
}
.footer-legal p { margin-bottom: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
}

/* Footer accordion toggle (mobile) */
.footer-col .accordion-toggle { display: none; }

/* --- Savings/Offers cards --- */
.offer-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.offer-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.offer-card-image {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.offer-card-body {
  padding: 20px;
  background: var(--color-card-bg);
}
.offer-card h3 { font-size: var(--fs-body); font-weight: 600; margin-bottom: 4px; }
.offer-card p { font-size: var(--fs-caption); color: var(--color-secondary); line-height: 1.4; }

/* --- Setup/Support Section --- */
.setup-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.setup-card {
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  padding: 28px 24px;
  text-align: center;
  transition: transform 0.3s, box-shadow 0.3s;
}
.setup-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.setup-card .card-emoji { font-size: 2.5rem; margin-bottom: 16px; }
.setup-card h3 { font-size: var(--fs-body); font-weight: 600; margin-bottom: 6px; }
.setup-card p { font-size: var(--fs-caption); color: var(--color-secondary); }

/* --- Responsive --- */
@media (max-width: 1068px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  .product-tile { min-height: 420px; padding: 40px 24px 0; }
  .product-tile.full-width { min-height: 460px; }
  .ent-panel.active { grid-template-columns: repeat(2, 1fr); }
  .brand-collab { flex-direction: column; padding: 40px 32px; }
  .brand-collab-visual { flex: none; width: 100%; height: 160px; }
}

@media (max-width: 734px) {
  :root {
    --section-padding: 48px;
    --carousel-gap: 12px;
  }

  .nav-links { gap: 16px; }
  .nav-links a { font-size: var(--fs-small); }

  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 380px; }
  .product-tile.full-width { min-height: 400px; grid-column: auto; }
  .product-tile h2 { font-size: var(--fs-h3); }
  .product-tile .tile-tagline { font-size: var(--fs-body); }

  .ent-panel.active { grid-template-columns: 1fr 1fr; }

  .product-card { flex: 0 0 240px; }
  .help-card, .diff-card, .guide-card, .save-card { flex: 0 0 240px; }
  .offer-card { flex: 0 0 220px; }

  .brand-collab { padding: 32px 24px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 0;
    margin-bottom: 0;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 1.2rem;
    font-weight: 300;
    color: var(--color-secondary);
    transition: transform 0.3s;
  }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
    padding-bottom: 0;
  }
  .footer-col.open ul {
    max-height: 500px;
    padding-bottom: 16px;
  }
}

@media (max-width: 480px) {
  .ent-panel.active { grid-template-columns: 1fr; }
  .ent-tabs { gap: 6px; }
  .ent-tab { padding: 8px 16px; font-size: var(--fs-small); }
  .tile-ctas { flex-direction: column; gap: 10px; }
  .store-hero .hero-links { flex-direction: column; gap: 10px; }
  .icon-bar { gap: 20px; justify-content: flex-start; }
}

/* ============================================================
   ORCHARD — Premium Tech E-Commerce Store
   Design System & Styles
   ============================================================ */

/* --- Design Tokens --- */
:root {
  --color-primary: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #004499;
  --color-bg: #fff;
  --color-bg-alt: #f5f5f7;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --color-white: #fff;
  --color-ribbon: #1d1d1f;

  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;

  --fs-display: clamp(2.5rem, 5vw, 3.5rem);
  --fs-h1: clamp(2rem, 4vw, 3rem);
  --fs-h2: clamp(1.75rem, 3.5vw, 2.5rem);
  --fs-h3: clamp(1.25rem, 2vw, 1.75rem);
  --fs-h4: 1.3125rem;
  --fs-body-lg: 1.3125rem;
  --fs-body: 1.0625rem;
  --fs-caption: 0.875rem;
  --fs-small: 0.75rem;

  --nav-height: 48px;
  --ribbon-height: 44px;
  --section-padding: 80px;
  --card-radius: 20px;
  --btn-radius: 22px;
  --max-width: 1200px;
  --carousel-gap: 16px;
}

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-stack);
  font-size: var(--fs-body);
  line-height: 1.47;
  color: var(--color-primary);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img { max-width: 100%; display: block; }
a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Ribbon Banner --- */
.ribbon {
  background: var(--color-ribbon);
  color: var(--color-white);
  text-align: center;
  padding: 12px 20px;
  font-size: var(--fs-caption);
  line-height: 1.43;
}
.ribbon a { color: var(--color-accent); }
.ribbon a:hover { text-decoration: underline; }

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  height: var(--nav-height);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}
.nav-logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
  text-decoration: none;
  letter-spacing: -0.02em;
}
.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}
.nav-links a {
  font-size: var(--fs-caption);
  color: var(--color-primary);
  text-decoration: none;
  opacity: 0.8;
  transition: opacity 0.2s;
}
.nav-links a:hover { opacity: 1; text-decoration: none; }
.nav-links a.active { opacity: 1; font-weight: 600; }
.nav-icons {
  display: flex;
  gap: 16px;
  align-items: center;
}
.nav-icons svg { width: 18px; height: 18px; fill: var(--color-primary); opacity: 0.8; }

/* --- Section Containers --- */
.section {
  padding: var(--section-padding) 0;
}
.section--alt {
  background: var(--color-bg-alt);
}
.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section-header {
  margin-bottom: 32px;
}
.section-header h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.section-header p {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 6px;
}

/* --- Hero (Store page) --- */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
}
.store-hero h1 {
  font-size: var(--fs-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}
.store-hero .subtitle {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 8px;
}
.store-hero .hero-links {
  margin-top: 16px;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: var(--fs-caption);
}

/* --- Product Icon Bar --- */
.icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  padding: 20px 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar a {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-primary);
  font-size: var(--fs-small);
  white-space: nowrap;
  min-width: 70px;
  transition: transform 0.2s;
}
.icon-bar a:hover { transform: translateY(-2px); text-decoration: none; }
.icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: background 0.2s;
}
.icon-bar a:hover .icon-circle { background: #e8e8ed; }

/* --- Carousel --- */
.carousel {
  position: relative;
  padding-bottom: 12px;
}
.carousel-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}
.carousel-top h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.carousel-top p {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 4px;
}
.carousel-arrows {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}
.carousel-arrow {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
  transition: background 0.2s, opacity 0.2s;
  border: 1px solid var(--color-border);
}
.carousel-arrow:hover { background: #e8e8ed; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }
.carousel-arrow svg { width: 16px; height: 16px; }

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px;
  padding-bottom: 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

/* --- Product Card (carousel) --- */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.product-card-image {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  position: relative;
  overflow: hidden;
}
.product-card-body {
  padding: 20px;
}
.product-card .badge {
  display: inline-block;
  font-size: var(--fs-small);
  font-weight: 600;
  color: #bf4800;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.product-card h3 {
  font-size: var(--fs-h4);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}
.product-card .tagline {
  color: var(--color-secondary);
  font-size: var(--fs-caption);
  margin-bottom: 12px;
  line-height: 1.4;
}
.product-card .price {
  font-size: var(--fs-body);
  font-weight: 600;
}
.product-card .monthly {
  font-size: var(--fs-caption);
  color: var(--color-secondary);
  margin-top: 2px;
}
.product-card .note {
  font-size: var(--fs-small);
  color: var(--color-accent);
  margin-top: 6px;
}

/* Card image color variants */
.card-bg-blue { background: linear-gradient(135deg, #d4e4f7 0%, #b8cfe8 100%); }
.card-bg-purple { background: linear-gradient(135deg, #e8daf5 0%, #d4c4eb 100%); }
.card-bg-peach { background: linear-gradient(135deg, #fde8d8 0%, #f5d4bc 100%); }
.card-bg-midnight { background: linear-gradient(135deg, #2d2d3a 0%, #1a1a2e 100%); color: #fff; }
.card-bg-teal { background: linear-gradient(135deg, #d0f0e8 0%, #b0e0d4 100%); }
.card-bg-rose { background: linear-gradient(135deg, #f5e0e8 0%, #ecc8d5 100%); }
.card-bg-silver { background: linear-gradient(135deg, #eaeaef 0%, #dddde3 100%); }
.card-bg-green { background: linear-gradient(135deg, #d4edda 0%, #b8dcc4 100%); }
.card-bg-warm { background: linear-gradient(135deg, #f5eadc 0%, #ede0d0 100%); }
.card-bg-orange { background: linear-gradient(135deg, #fde5c3 0%, #f5d4a8 100%); }
.card-bg-guava { background: linear-gradient(135deg, #f8c4c4 0%, #f0aaaa 100%); }
.card-icon {
  font-size: 3.5rem;
  opacity: 0.7;
}

/* --- Homepage Hero Product Grid --- */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.product-tile {
  border-radius: var(--card-radius);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  text-align: center;
  padding: 48px 32px 0;
  min-height: 500px;
  transition: transform 0.3s;
}
.product-tile:hover { transform: scale(1.005); }
.product-tile.full-width { grid-column: 1 / -1; min-height: 560px; }

.product-tile h2 {
  font-size: var(--fs-h1);
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 8px;
}
.product-tile .tile-tagline {
  font-size: var(--fs-body-lg);
  margin-bottom: 20px;
  max-width: 400px;
}
.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
}
.product-tile .tile-ctas a {
  font-size: var(--fs-body);
  font-weight: 400;
  padding: 8px 20px;
  border-radius: var(--btn-radius);
}
.btn-primary {
  background: var(--color-accent);
  color: var(--color-white) !important;
  transition: background 0.2s;
}
.btn-primary:hover { background: var(--color-accent-hover); text-decoration: none; }
.btn-secondary {
  background: transparent;
  border: 1px solid var(--color-accent);
  color: var(--color-accent) !important;
  transition: background 0.2s;
}
.btn-secondary:hover { background: rgba(0,102,204,0.06); text-decoration: none; }
.btn-secondary-light {
  border-color: rgba(255,255,255,0.6);
  color: var(--color-white) !important;
}
.btn-secondary-light:hover { background: rgba(255,255,255,0.12); }
.btn-primary-light {
  background: var(--color-white);
  color: var(--color-primary) !important;
}
.btn-primary-light:hover { background: rgba(255,255,255,0.85); }

.tile-dark { color: var(--color-white); }
.tile-dark .tile-tagline { color: rgba(255,255,255,0.8); }

.tile-image-area {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  opacity: 0.5;
  margin-top: 24px;
  width: 100%;
}

/* Tile background colors */
.tile-phone { background: linear-gradient(180deg, #1b1b3a 0%, #0f3460 100%); }
.tile-laptop-neo { background: linear-gradient(180deg, #faf8f5 0%, #f0ebe3 100%); }
.tile-tablet-pro { background: linear-gradient(180deg, #1a1a2e 0%, #2d1b4e 100%); }
.tile-laptop-pro { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.tile-earbuds { background: linear-gradient(180deg, #fef6ee 0%, #fde5c3 100%); }
.tile-tradein { background: linear-gradient(180deg, #004d40 0%, #00695c 100%); }

/* --- Entertainment Tabs --- */
.entertainment {
  padding: var(--section-padding) 0;
  background: var(--color-primary);
  color: var(--color-white);
}
.entertainment .section-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.entertainment h2 {
  font-size: var(--fs-h2);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}
.ent-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.ent-tab {
  padding: 10px 24px;
  border-radius: var(--btn-radius);
  font-size: var(--fs-caption);
  font-weight: 500;
  color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  transition: all 0.25s;
}
.ent-tab:hover { background: rgba(255,255,255,0.15); color: #fff; }
.ent-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  border-color: var(--color-white);
}
.ent-panel { display: none; }
.ent-panel.active { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.ent-card {
  border-radius: 16px;
  overflow: hidden;
  transition: transform 0.3s;
}
.ent-card:hover { transform: translateY(-4px); }
.ent-card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.ent-card-body {
  padding: 16px;
  background: rgba(255,255,255,0.06);
}
.ent-card-body h3 {
  font-size: var(--fs-body);
  font-weight: 600;
  margin-bottom: 8px;
}
.ent-card-body a {
  font-size: var(--fs-caption);
  color: var(--color-accent);
}
.ent-bg-1 { background: linear-gradient(135deg, #2d1b4e 0%, #4a1a6b 100%); }
.ent-bg-2 { background: linear-gradient(135deg, #1a3a5c 0%, #0f5c4a 100%); }
.ent-bg-3 { background: linear-gradient(135deg, #4a1a1a 0%, #6b3a1a 100%); }
.ent-bg-4 { background: linear-gradient(135deg, #1a2e4a 0%, #2d4a6b 100%); }

/* --- Help / Support Cards --- */
.help-card, .diff-card, .guide-card, .save-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  padding: 28px 24px;
  transition: transform 0.3s, box-shadow 0.3s;
}
.help-card:hover, .diff-card:hover, .guide-card:hover, .save-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.help-card .card-emoji, .diff-card .card-emoji, .guide-card .card-emoji, .save-card .card-emoji {
  font-size: 2rem;
  margin-bottom: 16px;
  display: block;
}
.help-card h3, .diff-card h3, .guide-card h3, .save-card h3 {
  font-size: var(--fs-h4);
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p, .diff-card p, .guide-card p, .save-card p {
  color: var(--color-secondary);
  font-size: var(--fs-caption);
  line-height: 1.5;
}

/* --- Brand Collab --- */
.brand-collab {
  border-radius: var(--card-radius);
  overflow: hidden;
  background: linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%);
  color: var(--color-white);
  padding: 60px 48px;
  display: flex;
  align-items: center;
  gap: 48px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.brand-collab-text { flex: 1; }
.brand-collab h2 { font-size: var(--fs-h2); font-weight: 700; letter-spacing: -0.02em; margin-bottom: 8px; }
.brand-collab p { color: rgba(255,255,255,0.75); font-size: var(--fs-body-lg); margin-bottom: 20px; }
.brand-collab-visual {
  flex: 0 0 300px;
  height: 200px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  opacity: 0.5;
}

/* --- Quick Links --- */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  padding: 40px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.quick-link {
  padding: 10px 24px;
  border-radius: var(--btn-radius);
  border: 1px solid var(--color-border);
  font-size: var(--fs-caption);
  color: var(--color-primary);
  background: var(--color-white);
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s;
}
.quick-link:hover { background: var(--color-bg-alt); border-color: #bbb; text-decoration: none; }

/* --- Sticky Section Navigation (Category Pages) --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 90;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section-nav a {
  padding: 14px 20px;
  font-size: var(--fs-caption);
  color: var(--color-secondary);
  white-space: nowrap;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.section-nav a:hover { color: var(--color-primary); text-decoration: none; }
.section-nav a.active {
  color: var(--color-primary);
  font-weight: 600;
  border-bottom-color: var(--color-primary);
}

/* --- Category Hero --- */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-alt);
}
.category-hero h1 {
  font-size: var(--fs-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}
.category-hero .subtitle {
  color: var(--color-secondary);
  font-size: var(--fs-body-lg);
  margin-top: 8px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Promo Banner (within sections) --- */
.promo-text {
  font-size: var(--fs-caption);
  color: var(--color-accent);
  margin-top: -16px;
  margin-bottom: 20px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

/* --- Footer --- */
.footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: 40px 0 24px;
  font-size: var(--fs-small);
  color: var(--color-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: var(--fs-caption);
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 12px;
  cursor: default;
}
.footer-col ul { display: flex; flex-direction: column; gap: 8px; }
.footer-col a {
  color: var(--color-secondary);
  font-size: var(--fs-small);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--color-primary); }
.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 16px;
  font-size: var(--fs-small);
  line-height: 1.6;
  color: #86868b;
}
.footer-legal p { margin-bottom: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
}

/* Footer accordion toggle (mobile) */
.footer-col .accordion-toggle { display: none; }

/* --- Savings/Offers cards --- */
.offer-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.offer-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.offer-card-image {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.offer-card-body {
  padding: 20px;
  background: var(--color-card-bg);
}
.offer-card h3 { font-size: var(--fs-body); font-weight: 600; margin-bottom: 4px; }
.offer-card p { font-size: var(--fs-caption); color: var(--color-secondary); line-height: 1.4; }

/* --- Setup/Support Section --- */
.setup-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.setup-card {
  border-radius: var(--card-radius);
  background: var(--color-card-bg);
  padding: 28px 24px;
  text-align: center;
  transition: transform 0.3s, box-shadow 0.3s;
}
.setup-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.setup-card .card-emoji { font-size: 2.5rem; margin-bottom: 16px; }
.setup-card h3 { font-size: var(--fs-body); font-weight: 600; margin-bottom: 6px; }
.setup-card p { font-size: var(--fs-caption); color: var(--color-secondary); }

/* --- Responsive --- */
@media (max-width: 1068px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  .product-tile { min-height: 420px; padding: 40px 24px 0; }
  .product-tile.full-width { min-height: 460px; }
  .ent-panel.active { grid-template-columns: repeat(2, 1fr); }
  .brand-collab { flex-direction: column; padding: 40px 32px; }
  .brand-collab-visual { flex: none; width: 100%; height: 160px; }
}

@media (max-width: 734px) {
  :root {
    --section-padding: 48px;
    --carousel-gap: 12px;
  }

  .nav-links { gap: 16px; }
  .nav-links a { font-size: var(--fs-small); }

  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 380px; }
  .product-tile.full-width { min-height: 400px; grid-column: auto; }
  .product-tile h2 { font-size: var(--fs-h3); }
  .product-tile .tile-tagline { font-size: var(--fs-body); }

  .ent-panel.active { grid-template-columns: 1fr 1fr; }

  .product-card { flex: 0 0 240px; }
  .help-card, .diff-card, .guide-card, .save-card { flex: 0 0 240px; }
  .offer-card { flex: 0 0 220px; }

  .brand-collab { padding: 32px 24px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 0;
    margin-bottom: 0;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 1.2rem;
    font-weight: 300;
    color: var(--color-secondary);
    transition: transform 0.3s;
  }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
    padding-bottom: 0;
  }
  .footer-col.open ul {
    max-height: 500px;
    padding-bottom: 16px;
  }
}

@media (max-width: 480px) {
  .ent-panel.active { grid-template-columns: 1fr; }
  .ent-tabs { gap: 6px; }
  .ent-tab { padding: 8px 16px; font-size: var(--fs-small); }
  .tile-ctas { flex-direction: column; gap: 10px; }
  .store-hero .hero-links { flex-direction: column; gap: 10px; }
  .icon-bar { gap: 20px; justify-content: flex-start; }
}

